pub(super) fn refill(&mut self) -> Result<u64, Error> {
    self.validate_frame()?;
    if self.frame.fuel != 0 { return Err(Error::Binding("packed-map fuel was renewed")); }
    let remaining = self.work.unscoped_remaining()
        .ok_or(Error::Binding("packed-map entered a foreign work scope"))?;
    let price = self.price(self.frame.capacity, self.frame.len)?;
    // Leave room on both dimensions for distinct-key insertion, table
    // growth and the corresponding remaining-body price increases.
    let count = (remaining.0 / price.compute.max(1) / 4)
        .min(remaining.1 / price.comparison.max(1) / 4).min(BATCH).max(1);
    let funded = add(self.funded, count)?;
    self.work.charge(mul(price.compute, count)?, mul(price.comparison, count)?)?;
    self.frame.fuel = count;
    self.issued = count;
    self.funded = funded;
    self.frame.entry_known = 0;
    self.frame.entry_pointer = 0;
    Ok(count)

pub fn unscoped_remaining(&self) -> Option<(u64, u64)> {
    if CONTROL_WORK.with(|v| v.borrow().is_some())
        || CONTROL_WORK_SCOPE.with(|v| v.borrow().is_some())
    {
        return None;
    }
    let root = CONTROL_ROOT_LIMITS
        .with(|v| v.get())
        .unwrap_or((u64::MAX, u64::MAX));
    let state = self.account.borrow();
    let local = (
        state
            .compute_limit
            .min(root.0)
            .checked_sub(state.used.compute)?.checked_sub(state.reserved.compute)?,
        state
            .comparison_limit
            .min(root.1)

    pub(super) fn remaining(&self) -> Option<(u64, u64)> {
        let state = self.shared.lock().unwrap_or_else(|error| error.into_inner());
        if state.sealed { return None; }
        Some((state.limit.compute - state.used.compute, state.limit.comparison - state.used.comparison))
    }
    pub(super) fn preview(&self, compute: u64, comparison: u64) -> Result<(), ResidentKernelError> {
        self.shared.lock().unwrap_or_else(|error| error.into_inner()).next(compute, comparison).map(drop)
    }
    pub(super) fn charge(&self, compute: u64, comparison: u64) -> Result<(), ResidentKernelError> {
        let mut state = self.shared.lock().unwrap_or_else(|error| error.into_inner());
        state.used = state.next(compute, comparison)?;
        Ok(())
    }
}
impl Drop for NativeWorkerWorkLoan {
    fn drop(&mut self) {
        let mut state = self.shared.lock().unwrap_or_else(|error| error.into_inner());
        state.live = state.live.checked_sub(1).expect("worker loan retired once");

    pub(super) fn charge(&self, compute: u64, comparison: u64) -> Result<(), ResidentKernelError> {
        let mut state = self.shared.lock().unwrap_or_else(|error| error.into_inner());
        state.used = state.next(compute, comparison)?;
        Ok(())
    }
